async ({ gh: { api }, workspace: { search, glob }, git: { tag, log } }) => {
  const [pr, checks, rel, wf, tags] = await Promise.allSettled([
    api("repos/{owner}/{repo}/pulls/94"),
    api("repos/{owner}/{repo}/commits/heads/" + "HEAD"),
    search("release", { path: "CONTRIBUTING.md", contextLines: 3, limit: 40 }),
    glob([".github/workflows/*.yml"]),
    tag(["--sort=-v:refname", "-l", "v*"]),
  ]);
  const p: any = pr.status === "fulfilled" ? pr.value : pr;
  return {
    pr: p.body ? { state: p.body.state, mergeable: p.body.mergeable, mergeable_state: p.body.mergeable_state, head: p.body.head?.sha, base: p.body.base?.ref, draft: p.body.draft } : JSON.stringify(p).slice(0, 2000),
    rel: rel.status === "fulfilled" ? rel.value : String(rel.reason),
    wf: wf.status === "fulfilled" ? wf.value : String(wf.reason),
    tags: tags.status === "fulfilled" ? (tags.value as any).stdout?.split("\n").slice(0, 5) : String(tags.reason),
  };
}
